    float sum = 0.0f;

    // parallel_reduce handles the entire reduction tree (thread-level, block-level, etc.)
    float final_sum = parallel_reduce(
        range(0, N), // The iteration space
        0.0f,        // Initial value (identity element for addition)
        [&](float current_sum, int i) {
            // This lambda is executed by each thread/worker.
            // It accumulates the value from the input data.
            return current_sum + data[i];
        },
        // Specify the execution policy
