### 2. RAJA Portable Code (Reduction)

RAJA provides `parallel_reduce` which handles the complex synchronization and reduction tree automatically.

```cpp
// RAJA Reduction Example
#include <raja/raja.hpp>
#include <iostream>
#include <vector>
#include <numeric> // For comparison

using namespace raja;
using backend = cuda; // Or hip, or openmp

// Function to perform the reduction using RAJA
float run_raja_reduction(const std::vector<float>& data, int N) {
    float sum = 0.0f;

    // parallel_reduce handles the entire reduction tree (thread-level, block-level, etc.)
    float final_sum = parallel_reduce(
        range(0, N), // The iteration space
        0.0f,        // Initial value (identity element for addition)
        [&](float current_sum, int i) {
            // This lambda is executed by each thread/worker.
            // It accumulates the value from the input data.
            return current_sum + data[i];
        },
        // Specify the execution policy
        policy<backend>{} 
    );

    return final_sum;
}

// --- Main function for testing ---
int main() {
    const int N = 1024 * 1024;
    std::vector<float> data(N);

    // Initialize data: 1.0, 2.0, 3.0, ...
    for (int i = 0; i < N; ++i) {
        data[i] = static_cast<float>(i + 1);
    }

    // Calculate expected sum using standard C++ (for verification)
    float expected_sum = std::accumulate(data.begin(), data.end(), 0.0f);

    std::cout << "Running RAJA Reduction..." << std::endl;

    // Run the RAJA parallel reduction
    float raja_sum = run_raja_reduction(data, N);

    std::cout << "Expected Sum: " << expected_sum << std::endl;
    std::cout << "RAJA Calculated Sum: " << raja_sum << std::endl;

    // Check if results match (allowing for minor floating point error)
    if (std::abs(expected_sum - raja_sum) < 1e-5) {
        std::cout << "Success: Results match!" << std::endl;
    } else {
        std::cout << "Failure: Results do not match." << std::endl;
